import source from '../../src/__tests__/fixtures/exp04-client-status-source.json';
export const control = { mode: 'empty',
  context: { activeTenantId: source.tenant_id, activeUserId: 'e0400000-0000-4000-8000-000000000001',
    accountContextLoading: false, accountContextStatus: 'ready' } };
export const useTenantContext = () => control.context;
export const fixture = source;
export const supabase = {
  async rpc(name: string) {
    if(name !== 'read_client_engagement_status') throw Error('Prototype forbids other backend calls.');
    if(control.mode === 'loading') return new Promise(() => {});
    if(control.mode === 'refused') return { data: null, error: { code: '42501' } };
    if(control.mode === 'error') return { data: null, error: { code: 'PGRST' } };
    const record = structuredClone(source);
    if(control.mode === 'empty') { record.terms = []; record.signings = []; record.invoices = [];
      record.work = { ...record.work, total: 0, done: 0, open: 0, overdue: 0, blocked: 0, cancelled: 0, undated_open: 0, items: [] }; }
    return { data: { ...record, receipt_id: undefined }, error: null };
  },
};

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react-swc';
import path from 'node:path';
const repo = path.resolve(__dirname, '../..');
export default defineConfig({ root: __dirname, publicDir: path.join(repo, 'public'), plugins: [react()],
  resolve: { alias: { '@/hooks/useTenantContext': path.join(__dirname, 'ports.ts'),
    '@/integrations/supabase/client': path.join(__dirname, 'ports.ts'), '@': path.join(repo, 'src') } },
  server: { host: '127.0.0.1', port: 5286, strictPort: true, fs: { allow: [repo] } },
});

import React, { useCallback, useEffect, useState, useSyncExternalStore } from 'react';
import { createRoot } from 'react-dom/client';
import { MemoryRouter } from 'react-router-dom';
import { ClientStanding } from '../../src/components/tenant-relationships/ClientStanding';
import { clearPaigeClientScope, getPaigeClientScope, subscribePaigeClientScope } from '../../src/solo/paigeClientScope';
import { mergeIntoDraft, subscribePaigePromptHandoff } from '../../src/lib/paigePromptHandoff';
import { createComposerScopeIdentity, initialComposerConversation, resolveComposerScopeState, setComposerDraftSessionScope, useComposerDraft } from '../../src/lib/paigeComposerScopeState';
import { Textarea } from '../../src/components/ui/textarea';
import { control, fixture } from './ports';
import '../../src/index.css';
import '../../src/components/tenant-relationships/tenant-relationships-clients-workspace.css';
import './prototype.css';

setComposerDraftSessionScope({ kind: 'ready', tenantId: control.context.activeTenantId, userId: control.context.activeUserId });
function Composer() {
  const snapshot = useCallback(() => getPaigeClientScope(control.context.activeTenantId), []);
  const scope = useSyncExternalStore(subscribePaigeClientScope, snapshot, () => null);
  const identity = createComposerScopeIdentity({ tenantId: control.context.activeTenantId, userId: control.context.activeUserId, focusedClientId: scope?.clientId });
  const draft = useComposerDraft(resolveComposerScopeState({ currentIdentity: identity, displayedIdentity: identity,
    conversation: initialComposerConversation(false, 'c56-prototype'), busy: false }));
  useEffect(() => subscribePaigePromptHandoff(prompt => draft.setValue(current => mergeIntoDraft(current, prompt, { preserveAddressee: true }))), [draft.setValue]);
  return <section className="c56-composer" aria-label="Controlled composer port">
    <h2>PAIGE</h2><p role="status">{scope ? `Selected client: ${scope.label}` : 'Business conversation'}</p>
    <p>Canonical scope, draft storage and merger; controlled visual port. No Chat backend or send.</p>
    <label htmlFor="c56-question">Review your unsent question</label>
    <Textarea id="c56-question" value={draft.value} onChange={event => draft.setValue(event.target.value)} />
    <div className="c56-actions"><button onClick={() => draft.setValue('Keep my original unsent note.')}>Seed a draft</button>
      <button onClick={() => clearPaigeClientScope()}>Return to business draft</button><button onClick={() => draft.setValue('')}>Clear this draft</button></div>
    <p>No message has been sent. Actual model, authorization and read receipt remain unverified by this prototype.</p>
  </section>;
}
function Prototype() {
  const [mode, setMode] = useState('empty'), [frame, setFrame] = useState(0), [open, setOpen] = useState(false);
  const [theme, setTheme] = useState('light');
  return <main className="paige-solo solo-campaigns c56-prototype" data-pg={theme} data-theme={theme}>
    <aside className="c56-controls" aria-label="Prototype controls"><strong>Local flow prototype · synthetic records · no backend effects</strong>
      <label>Record state <select value={mode} onChange={event => { const next = event.target.value; control.mode = next; setMode(next); setFrame(current => current + 1); }}>
        {['empty','populated','loading','refused','error'].map(value => <option key={value}>{value}</option>)}</select></label>
      <label>Theme <select value={theme} onChange={event => setTheme(event.target.value)}><option value="light">Mineral</option><option value="dark">Obsidian</option></select></label>
      <button onClick={() => setOpen(value => !value)}>{open ? 'Fold composer' : 'Open composer'}</button>
    </aside>
    <div className="c56-panels"><article className="trc-record-section c56-record"><h1>Client standing</h1>
      <ClientStanding key={frame} contactId={fixture.contact_id} clientName="Synthetic consulting client" account="123" openPaige={() => setOpen(true)} />
    </article><div hidden={!open}><Composer /></div></div>
  </main>;
}
createRoot(document.getElementById('root')!).render(<MemoryRouter><Prototype /></MemoryRouter>);

.c56-prototype{height:100dvh;background:var(--pg-canvas);color:var(--pg-ink);display:flex;flex-direction:column;font-family:var(--pg-font-body)}
.c56-controls{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:16px;border-bottom:1px solid var(--pg-line);background:var(--pg-surface)}
.c56-controls strong{flex-basis:100%;font-size:14px}.c56-controls label{display:flex;gap:8px;align-items:center;font-size:13px}
.c56-controls select,.c56-controls button,.c56-actions button{min-height:44px;border:1px solid var(--pg-line);border-radius:var(--pg-r-chip);background:var(--pg-canvas);color:var(--pg-ink);padding:8px 12px}
.c56-panels{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,440px);gap:24px;padding:24px;min-height:0;overflow:auto;align-items:start}
.c56-record{min-width:0}.c56-record h1{font-size:24px;margin:0 0 24px}.c56-composer{padding:20px;background:var(--pg-surface);border:1px solid var(--pg-line);border-radius:var(--pg-r-plate);min-width:0}
.c56-composer h2{font-size:20px}.c56-composer p{font-size:14px;line-height:1.55;margin:12px 0;color:var(--pg-muted)}.c56-composer label{display:block;margin:16px 0 8px}
.c56-composer textarea{min-height:220px;background:var(--pg-canvas);color:var(--pg-ink);font-size:16px;line-height:1.55}.c56-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}
.c56-prototype button:focus-visible,.c56-prototype select:focus-visible{outline:2px solid var(--pg-violet);outline-offset:3px}
@media(max-width:760px){.c56-panels{grid-template-columns:minmax(0,1fr);padding:16px;gap:16px}.c56-controls{padding:12px}.c56-record h1{font-size:21px}}
